#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Regenerate the host resource from the two deterministic RV64 binaries."""
from pathlib import Path
root = Path(__file__).resolve().parent
out = ['/* Generated by make native-resources; SPDX-License-Identifier: GPL-2.0-or-later */']
for name, filename in [('kmh_native_entry', 'native-entry.bin'),
                       ('kmh_native_firmware', 'native.bin')]:
    data = (root / 'build' / filename).read_bytes()
    out.append(f'static const uint8_t {name}[] = {{')
    out += ['    ' + ', '.join(f'0x{x:02x}' for x in data[i:i + 16]) + ','
            for i in range(0, len(data), 16)]
    out.append('};')
(root / 'native-resources.inc').write_text('\n'.join(out) + '\n')
